CREATE OR REPLACE VIEW vw_income_expenses AS SELECT user_id,date_trunc('month',tx_date)::date AS period_month,SUM(gross_amount) FILTER(WHERE type='income' AND NOT archived) AS income,SUM(gross_amount) FILTER(WHERE type='expense' AND NOT archived) AS expense FROM transactions GROUP BY user_id,date_trunc('month',tx_date);
CREATE OR REPLACE VIEW vw_monthly_finance AS SELECT *,COALESCE(income,0)-COALESCE(expense,0) AS surplus FROM vw_income_expenses;
CREATE OR REPLACE VIEW vw_category_expenses AS SELECT t.user_id,c.name AS category,date_trunc('month',t.tx_date)::date AS period_month,SUM(t.gross_amount) AS amount FROM transactions t LEFT JOIN categories c ON c.id=t.category_id WHERE t.type='expense' AND NOT t.archived GROUP BY t.user_id,c.name,date_trunc('month',t.tx_date);
CREATE OR REPLACE VIEW vw_account_balances AS SELECT a.id,a.user_id,a.name,a.opening_balance+COALESCE(SUM(CASE WHEN t.type='income' THEN t.gross_amount ELSE -t.gross_amount END) FILTER(WHERE NOT t.archived),0) AS balance FROM accounts a LEFT JOIN transactions t ON t.account_id=a.id GROUP BY a.id;
CREATE OR REPLACE VIEW vw_tax_overview AS SELECT user_id,date_trunc('month',tx_date)::date AS period_month,SUM(tax_amount) FILTER(WHERE type='income' AND tax_relevant) AS output_tax,SUM(tax_amount) FILTER(WHERE type='expense' AND tax_relevant) AS input_tax FROM transactions GROUP BY user_id,date_trunc('month',tx_date);
CREATE OR REPLACE VIEW vw_business_private AS SELECT user_id,scope,type,SUM(gross_amount) AS amount FROM transactions WHERE NOT archived GROUP BY user_id,scope,type;
CREATE OR REPLACE VIEW vw_cashflow AS SELECT user_id,tx_date,SUM(CASE WHEN type='income' THEN gross_amount ELSE -gross_amount END) AS daily_cashflow FROM transactions WHERE NOT archived GROUP BY user_id,tx_date;
CREATE OR REPLACE VIEW vw_customer_revenue AS SELECT t.user_id,c.id AS customer_id,c.name,SUM(t.gross_amount) AS revenue FROM transactions t JOIN customers c ON c.id=t.customer_id WHERE t.type='income' AND NOT t.archived GROUP BY t.user_id,c.id,c.name;
